package za.ac.univen.clone;
import java.util.*;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import org.jsoup.Jsoup;
class PortalSession {
 final String studentNumber;private final PortalTransport transport;private final Map<String,String> cookies=new LinkedHashMap<>();private boolean revoked;private byte[] residencePdf;
 PortalSession(String studentNumber,PortalTransport transport){this.studentNumber=studentNumber;this.transport=transport;}
 private PortalTransport.Reply response(String path,String body){if(revoked)throw ApiProblem.expired();var reply=transport.request(path,String.join("; ",cookies.entrySet().stream().map(e->e.getKey()+"="+e.getValue()).toList()),body);for(String cookie:reply.cookies()){String pair=cookie.split(";",2)[0];int split=pair.indexOf('=');if(split>0)cookies.put(pair.substring(0,split).trim(),pair.substring(split+1));}if(reply.status()==401||reply.status()==403)throw ApiProblem.expired();if(reply.status()!=200)throw ApiProblem.changed();return reply;}
 private String request(String path){return response(path,null).html();}
 synchronized Map<String,Object> login(String pin){String html=response("w99pkg.mi_validate_user","numtype=S&unum="+studentNumber+"&pin="+URLEncoder.encode(pin,StandardCharsets.UTF_8)+"&authorise_function=Login").html();if(html.matches("(?is).*(Maximum Unsuccessful Login Attempts|Illegal Login|Invalid Login|Access Denied).*"))throw ApiProblem.expired();String id=Data.match("JsCreate_Cookie\\([\"']([^\"']+)[\"'],\\s*[\"']sessid[\"']\\)",html);if(id.matches("[\\w%-]+"))cookies.put("sessid",id);if(!cookies.containsKey("sessid"))throw ApiProblem.expired();String profile=verify();return PortalParser.profile(profile,studentNumber);}
 synchronized String verify(){String html=request("w99pkg.mi_frame_main");PortalParser.verifyProfile(html,studentNumber);return html;}
 synchronized void revoke(){revoked=true;cookies.clear();residencePdf=null;}
 private PortalTransport.Reply openMenu(String parent,String label,String expectedPath){var frames=Jsoup.parse(request("w99pkg.mi_main_menu")).select("iframe,frame").stream().filter(e->e.attr("src").split("[?#]",2)[0].equals("w99pkg.mi_frame_menu")).toList();if(frames.size()!=1)throw ApiProblem.changed();var entries=PortalParser.menu(request(frames.getFirst().attr("src"))).stream().filter(e->(label.equalsIgnoreCase(e.label())||e.label().toLowerCase().startsWith(label.toLowerCase())||label.toLowerCase().startsWith(e.label().toLowerCase()))&&parent.equalsIgnoreCase(e.parent())).toList();if(entries.isEmpty()||entries.size()>3)throw ApiProblem.changed();for(var entry:entries){var destination=PortalTransport.allowed(entry.url());if(!destination.getPath().equals("/pls/prodi41/w99pkg.mi_validate_option"))throw ApiProblem.changed();String redirect=Data.match("location\\.replace\\(\"([^\"\\n]+)\"\\)",request(destination.toString()));if(redirect.isEmpty())throw ApiProblem.changed();var target=PortalTransport.allowed(redirect);if(expectedPath==null||expectedPath.isEmpty()||target.getPath().equals("/pls/prodi41/"+expectedPath)||target.getPath().matches("/pls/prodi41/("+expectedPath+")"))return response(target.toString(),null);}throw ApiProblem.changed();}
 private PortalTransport.Reply openSection(String section){var contract=PortalParser.CONTRACTS.get(section);String parent=switch(section){case "contacts"->"Student Administration";case "residenceProof"->"Residence Registration";case "residenceApplications"->"Residence Application";default->"Student Enquiry";};return openMenu(parent,contract.label(),contract.path());}
 static byte[] pdf(PortalTransport.Reply reply){if(!reply.contentType().toLowerCase().startsWith("application/pdf")||reply.bytes().length<5||!new String(reply.bytes(),0,5,StandardCharsets.US_ASCII).equals("%PDF-"))throw new ApiProblem(502,"NOT_AVAILABLE","The portal did not return a PDF document.");return reply.bytes();}
 synchronized byte[] academicProof(){verify();return pdf(openMenu("Academic Registration","Proof of Registration - PDF","ws25pkg.ws25_por"));}
 synchronized byte[] examAdmissionSlip(){verify();return pdf(openMenu("Student Enquiry","Exam Admission Slip","ws11pkg.*|w.*exam.*|.*adm.*|ws11_exam_adm.*"));}
 synchronized byte[] residenceProof(){verify();if(residencePdf==null)throw new ApiProblem(404,"NOT_AVAILABLE","Open residence proof first.");return residencePdf;}
 synchronized Map<String,Object> read(String section){if(!PortalParser.CONTRACTS.containsKey(section))throw new ApiProblem(404,"NOT_AVAILABLE","Unknown portal section.");verify();var reply=openSection(section);if(section.equals("residenceProof")){residencePdf=pdf(reply);return PortalParser.result(List.of(),List.of(Data.map("label","Document","value","Residence proof of registration")),List.of(),null,false);}if(section.equals("progress"))return PortalParser.progress(reply.html(),studentNumber);var result=PortalParser.read(reply.html(),section,studentNumber);if(!section.equals("results"))return result;
  var tables=Data.list(Data.obj(result.get("data")).get("tables"));var warnings=new ArrayList<String>();for(var row:Data.list(tables.getFirst().get("rows"))){var cells=(List<?>)row.get("cells");String code=Data.str(cells.getFirst()),year=Data.str(cells.get(2));try{var page=Jsoup.parse(openSection("results").html());var matching=page.select("tr.rldata").stream().filter(r->{var c=PortalParser.cells(r);return c.size()>2&&c.getFirst().equals(code)&&c.get(2).equals(year);}).toList();if(matching.size()!=1||matching.getFirst().select("a").size()!=1)throw ApiProblem.changed();String href=matching.getFirst().selectFirst("a").attr("href");if(!PortalTransport.allowed(href).getPath().equals("/pls/prodi41/w68pkg.w68_lst_frma1"))throw ApiProblem.changed();tables.add(PortalParser.detail(request(href),studentNumber,code));}catch(ApiProblem e){if(e.status==401||e.status==403)throw e;warnings.add("Assessment detail could not be read for "+code+".");}}
  result.put("warnings",warnings);if(!warnings.isEmpty())result.put("status","partial");return result;
 }
}
